mapper.sql:
p.deleted = 0 and p.listing_status = 1
and (p.unlisting_at is null or p.unlisting_at > now())

    AND (p.product_name LIKE concat('%', #{keyword}, '%')
      OR p.product_subtitle LIKE concat('%', #{keyword}, '%')
      OR p.category_name LIKE concat('%', #{keyword}, '%'))



        AND p.product_type_id NOT IN (
            SELECT id FROM pt_product_type
            WHERE deleted = 0 AND type_name IN ('体验服务', '团课', '小班课')
        )


        AND p.product_type_id IN (
            SELECT id FROM pt_product_type
            WHERE deleted = 0 AND type_name IN ('团课', '小班课')
        )


        AND p.product_type_id IN (
            SELECT id FROM pt_product_type
            WHERE deleted = 0 AND type_name = '体验服务'
        )



    AND p.product_type_id = #{productTypeId}


    AND p.category_id = #{categoryId}


    AND p.service_type = #{serviceType}


    AND p.sale_price >= #{minPrice}


    AND p.sale_price <= #{maxPrice}


    AND p.id IN (select product_id from pt_product_store_rel where store_id = #{storeId})

mapper.select:
select from pt_product p where
order by p.sale_price asc, p.id desc order by p.sale_price desc, p.id desc order by p.id desc order by p.sort_no desc, p.id desc
limit #{offset}, #{limit}
